/**
 * Renders a component's runtime environment as a ConfigMap (plain values) and
 * a Secret (encrypted values, before SOPS encryption), the documents a
 * deployment consumes with envFrom. Names, keys and annotations are kept from
 * the predecessor so existing workloads and their checks keep working.
 *
 * Keys and values are written as JSON strings: a key containing a newline
 * could otherwise break out of `data` and inject document-level fields.
 */
import { createHmac } from "node:crypto";
import type { MergedEnv } from "./merge.ts";

export const ENV_REVISION_ANNOTATION = "stardust.io/env-revision";
export const ATTACH_OPERATION_ANNOTATION = "stardust.io/database-attach-operation";

const NAME = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$/;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

export const HEADER =
  "# Generated by stardust from the env layers in deploy/env/. Do not edit:\n" +
  "# the next change rewrites this file. Change the layers instead.\n";

export function envConfigMapName(component: string): string {
  return `${component}-env`;
}

export function envSecretName(component: string, operationId?: string): string {
  if (operationId === undefined) return `${component}-env-secret`;
  if (!UUID.test(operationId)) throw new Error("operationId must be a UUID");
  const name = `${component}-env-secret-${operationId}`;
  if (name.length > 63) throw new Error("component name is too long for an operation-bound env Secret");
  return name;
}

/**
 * A fingerprint of every key and value, keyed with a secret so it reveals
 * nothing about the values. Computed from the plain values, never from the
 * ciphertext: SOPS output differs on every encryption.
 */
export function envRevision(plain: Record<string, string>, enc: Record<string, string>, key: string): string {
  const sorted = (o: Record<string, string>) => Object.entries(o).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
  return createHmac("sha256", key)
    .update(JSON.stringify([sorted(plain), sorted(enc)]))
    .digest("hex")
    .slice(0, 16);
}

export interface RenderEnvInput {
  merged: readonly MergedEnv[];
  component: string;
  namespace: string;
  /** Key for the revision fingerprint. */
  revisionKey: string;
  operationId?: string;
}

export interface RenderedEnv {
  configMapYaml: string;
  /** The Secret before encryption. The caller encrypts it with SOPS. */
  secretYaml: string;
  names: { configMap: string; secret: string };
  revision: string;
}

function document(
  kind: "ConfigMap" | "Secret",
  name: string,
  namespace: string,
  entries: Record<string, string>,
  annotations: Array<[string, string]>,
): string {
  const lines = ["apiVersion: v1", `kind: ${kind}`, "metadata:", `  name: ${name}`, `  namespace: ${namespace}`];
  if (annotations.length > 0) lines.push("  annotations:", ...annotations.map(([k, v]) => `    ${k}: ${v}`));
  lines.push(...(kind === "Secret" ? ["type: Opaque", "stringData:"] : ["data:"]));
  const pairs = Object.entries(entries);
  if (pairs.length === 0) lines.push("  {}");
  for (const [k, v] of pairs) lines.push(`  ${JSON.stringify(k)}: ${JSON.stringify(v)}`);
  return `${lines.join("\n")}\n`;
}

export function renderEnv(input: RenderEnvInput): RenderedEnv {
  if (!NAME.test(input.component)) throw new Error(`component "${input.component}" is not a DNS label`);
  if (!NAME.test(input.namespace)) throw new Error(`namespace "${input.namespace}" is not a DNS label`);
  const plain: Record<string, string> = {};
  const enc: Record<string, string> = {};
  for (const e of input.merged) {
    if (e.scope !== "runtime") continue;
    if (e.enc) enc[e.key] = e.value;
    else plain[e.key] = e.value;
  }
  const names = {
    configMap: envConfigMapName(input.component),
    secret: envSecretName(input.component, input.operationId),
  };
  const revision = envRevision(plain, enc, input.revisionKey);
  const annotations: Array<[string, string]> = [];
  if (input.operationId) annotations.push([ATTACH_OPERATION_ANNOTATION, input.operationId]);
  annotations.push([ENV_REVISION_ANNOTATION, revision]);
  return {
    configMapYaml: HEADER + document("ConfigMap", names.configMap, input.namespace, plain, annotations),
    secretYaml: document("Secret", names.secret, input.namespace, enc, annotations),
    names,
    revision,
  };
}
